import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TextInput, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {isEmpty} from 'lodash';
import {Color} from '../../../../../constants';
import {
  IconBlackClose,
  IconGreyFilter,
  IconGreySearch,
} from '../../../../../assets/images';

type Props = {
  searchText: string;
  setSearchText: (text: string) => void;
  onPressFilter: () => void;
};

const InputSearch = ({searchText, setSearchText, onPressFilter}: Props) => {
  const {t} = useTranslation();

  const [isFocused, setIsFocused] = useState(false);

  return (
    <View style={styles.container}>
      <View
        style={[styles.viewInput, isFocused && {borderColor: Color.Primary}]}>
        <IconGreySearch width={16} height={16} />
        <TextInput
          allowFontScaling={false}
          value={searchText}
          style={styles.textInput}
          placeholder={t('NT.TxtSearch')}
          placeholderTextColor={'#667085'}
          onChangeText={setSearchText}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
        />
        {!isEmpty(searchText) && (
          <TouchableOpacity onPress={() => setSearchText('')} hitSlop={15}>
            <IconBlackClose width={12} height={12} />
          </TouchableOpacity>
        )}
      </View>
      <TouchableOpacity style={styles.btnFilter} onPress={onPressFilter}>
        <IconGreyFilter width={20} height={20} />
      </TouchableOpacity>
    </View>
  );
};

export default InputSearch;
