import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {IconRoundDocument, IconRoundUser} from '../../../../assets/images';
import {View} from 'react-native';
import TextCM from '../../../../components/Text';
import {IHomeScreen} from '../../interface';

type DataType = {
  title: string;
  value: number;
  icon: React.ReactNode;
};

const Statistical = ({dataHomeScreen}: {dataHomeScreen: IHomeScreen}) => {
  const {t} = useTranslation();

  const data: DataType[] = [
    {
      title: t('HM.TxtNumberIncompleteDocument'),
      value: dataHomeScreen.numberIncompleteDocument,
      icon: <IconRoundDocument width={30} height={30} />,
    },
    {
      title: t('HM.TxtNumberUserOrganization'),
      value: dataHomeScreen.numberUserOrganization,
      icon: <IconRoundUser width={30} height={30} />,
    },
    {
      title: t('HM.TxtNumberUserSubUnits'),
      value: dataHomeScreen.numberUserSubUnits,
      icon: <IconRoundUser width={30} height={30} />,
    },
  ];

  const renderItem = (item: DataType) => {
    return (
      <View style={styles.viewItem} key={item.title}>
        {item.icon}
        <View>
          <TextCM style={styles.txtValue}>{formatNumber(item.value)}</TextCM>
          <TextCM style={styles.txtName}>{item.title}</TextCM>
        </View>
      </View>
    );
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('HM.TxtStatistical')}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default Statistical;
