import {useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import {mapRoleRecipientToUi} from '../../helper';
import styles from './styles';
import TextCM from '../../../../../../components/Text';
import React from 'react';
import {
  IconBlackDown,
  IconBlackUp,
  IconBlueFullfillPen,
} from '../../../../../../assets/images';
import {SignType} from '../../../../../../model/interface/notification.interface';

interface Props {
  data: any;
  onPressCaOtp?: (recipientData: any) => void;
}

const CardInfoRecipient = ({data, onPressCaOtp}: Props) => {
  const [toggle, setToggle] = useState(false);

  const onToggle = () => {
    setToggle(!toggle);
  };

  const handleOnpressCaOtp = (recipientData: any) => () => {
    if (onPressCaOtp) {
      onPressCaOtp(recipientData);
    }
  };

  const groupByRole = (data: any) => {
    // Use reduce to group objects by role
    return data.reduce((acc: any, item: any) => {
      // Check if an array for the role already exists, if not create one
      const roleIndex = acc.findIndex(
        (group: any) => group[0].role === item.role,
      );
      if (roleIndex === -1) {
        // If the role group does not exist, create a new group
        acc.push([{role: item.role, ...item}]);
      } else {
        // If the role group exists, add the item to the existing group
        acc[roleIndex].push({role: item.role, ...item});
      }
      return acc;
    }, []);
  };

  const newData = groupByRole(data?.recipients);

  return (
    <View style={styles.ctn}>
      <View style={styles.rowCtn}>
        <TextCM>{data?.name}</TextCM>
        <View style={styles.squareCtn}>
          <TextCM>{data?.order}</TextCM>
        </View>
      </View>
      {newData.map((i: any) => {
        return (
          <>
            <View style={styles.itemCtn}>
              <TouchableOpacity onPress={onToggle}>
                <View style={styles.groupLabelItemCtn}>
                  <View style={styles.logoItemCtn}>
                    {mapRoleRecipientToUi(i[0].role).icon}
                    <TextCM style={styles.txtLabelItem}>
                      {`${mapRoleRecipientToUi(i[0].role).label}`} ({i.length})
                    </TextCM>
                  </View>
                  {toggle ? (
                    <IconBlackUp width={14} height={12} />
                  ) : (
                    <IconBlackDown width={14} height={12} />
                  )}
                </View>
              </TouchableOpacity>
              {toggle &&
                i?.map((item: any, index: number) => {
                  return (
                    <ItemInfoRecipient
                      onPressCaOtp={handleOnpressCaOtp(item)}
                      data={item}
                      key={item.id}
                    />
                  );
                })}
            </View>
          </>
        );
      })}
    </View>
  );
};

const ItemInfoRecipient = ({data, onPressCaOtp}: any) => {
  const handleOnpressCaOtp = () => {
    onPressCaOtp?.(data);
  };

  return (
    <View style={{...styles.itemCtn, padding: 0}}>
      <View style={styles.infoItemCtn}>
        <View style={styles.groupNameCtn}>
          {data.signTypes.includes(SignType.FPTOTP) ? (
            <TouchableOpacity onPress={handleOnpressCaOtp} style={styles.row}>
              <TextCM style={[data?.username && styles.txtBlue]}>
                {data.contact.name}
              </TextCM>
              <IconBlueFullfillPen width={14} height={14} />
            </TouchableOpacity>
          ) : (
            <TextCM>{data.contact.name}</TextCM>
          )}
          <View style={styles.groupAddressCtn}>
            <TextCM style={styles.txt14Item}>{data.contact?.email}</TextCM>
            <View style={styles.verticalSeparate} />
            <TextCM style={styles.txt14Item}>{data.contact?.phone}</TextCM>
          </View>
        </View>
        <View style={styles.squareCtn}>
          <TextCM>{data.order}</TextCM>
        </View>
      </View>
    </View>
  );
};

export default CardInfoRecipient;
